#include "swan/parser.hpp"
#include <utility>
namespace swan {
const Token& Parser::peek(std::size_t n)const{return tokens_[pos_+n<tokens_.size()?pos_+n:tokens_.size()-1];}
bool Parser::match(TokenKind k){if(peek().kind!=k)return false;++pos_;return true;}
bool Parser::expect(TokenKind k,const char* m){if(match(k))return true;errors_.push_back(std::string(m)+" at line "+std::to_string(peek().location.line));return false;}
void Parser::synchronize(){while(peek().kind!=TokenKind::End&&peek().kind!=TokenKind::KwFunc)++pos_;}
std::string Parser::typeName(){auto k=peek().kind;if(k==TokenKind::Identifier|| (k>=TokenKind::KwInt&&k<=TokenKind::KwF64)){auto s=peek().lexeme;++pos_;return s;}errors_.push_back("expected type at line "+std::to_string(peek().location.line));return "void";}
Module Parser::parse(){Module m;while(peek().kind!=TokenKind::End){try{if(peek().kind==TokenKind::KwFunc)m.functions.push_back(function());else{errors_.push_back("expected 'func' at line "+std::to_string(peek().location.line));synchronize();}}catch(...){synchronize();}}return m;}
FunctionDecl Parser::function(){FunctionDecl f;expect(TokenKind::KwFunc,"expected func");if(peek().kind==TokenKind::Identifier){f.name=peek().lexeme;++pos_;}else errors_.push_back("expected function name");expect(TokenKind::LParen,"expected '('");if(peek().kind!=TokenKind::RParen){do{std::string n=peek().lexeme;if(peek().kind==TokenKind::Identifier)++pos_;else errors_.push_back("expected parameter name");expect(TokenKind::Colon,"expected ':'");f.params.push_back({n,typeName()});}while(match(TokenKind::Comma));}expect(TokenKind::RParen,"expected ')'");if(match(TokenKind::Arrow))f.returnType=typeName();f.body=block();return f;}
std::unique_ptr<BlockStmt> Parser::block(){auto b=std::make_unique<BlockStmt>();if(!expect(TokenKind::LBrace,"expected '{'"))return b;while(peek().kind!=TokenKind::RBrace&&peek().kind!=TokenKind::End)b->statements.push_back(statement());expect(TokenKind::RBrace,"expected '}'");return b;}
std::unique_ptr<Stmt> Parser::statement(){if(match(TokenKind::KwReturn)){auto s=std::make_unique<ReturnStmt>();if(peek().kind!=TokenKind::Semicolon&&peek().kind!=TokenKind::RBrace)s->value=expression();match(TokenKind::Semicolon);return s;}
if(match(TokenKind::KwLet)||match(TokenKind::KwVar)||match(TokenKind::KwConst)){auto k=tokens_[pos_-1].kind;auto s=std::make_unique<VarStmt>();s->mutableValue=k==TokenKind::KwVar;if(peek().kind==TokenKind::Identifier)s->name=peek().lexeme,++pos_;else errors_.push_back("expected variable name");if(match(TokenKind::Colon))s->type=typeName();if(match(TokenKind::Equal))s->value=expression();match(TokenKind::Semicolon);return s;}
if(match(TokenKind::KwIf)){auto s=std::make_unique<IfStmt>();s->condition=expression();s->thenBranch=block();if(match(TokenKind::KwElse))s->elseBranch=peek().kind==TokenKind::KwIf?statement():block();return s;}
if(match(TokenKind::KwWhile)){auto s=std::make_unique<WhileStmt>();s->condition=expression();s->body=block();return s;}
if(peek().kind==TokenKind::LBrace)return block();auto s=std::make_unique<ExprStmt>();s->value=expression();match(TokenKind::Semicolon);return s;}
static int precedence(TokenKind k){switch(k){case TokenKind::EqualEqual:case TokenKind::BangEqual:return 1;case TokenKind::Less:case TokenKind::LessEqual:case TokenKind::Greater:case TokenKind::GreaterEqual:return 2;case TokenKind::Plus:case TokenKind::Minus:return 3;case TokenKind::Star:case TokenKind::Slash:case TokenKind::Percent:return 4;default:return -1;}}
std::unique_ptr<Expr> Parser::expression(int min){auto lhs=primary();while(precedence(peek().kind)>=min){auto op=peek().kind;int p=precedence(op);++pos_;auto rhs=expression(p+1);auto b=std::make_unique<BinaryExpr>();b->op=op;b->lhs=std::move(lhs);b->rhs=std::move(rhs);lhs=std::move(b);}return lhs;}
std::unique_ptr<Expr> Parser::primary(){if(match(TokenKind::Minus)||match(TokenKind::Bang)){auto u=std::make_unique<UnaryExpr>();u->op=tokens_[pos_-1].kind;u->rhs=primary();return u;}if(match(TokenKind::LParen)){auto e=expression();expect(TokenKind::RParen,"expected ')'");return e;}auto k=peek().kind;if(k==TokenKind::Integer||k==TokenKind::Float||k==TokenKind::String||k==TokenKind::KwTrue||k==TokenKind::KwFalse||k==TokenKind::KwNull){auto v=peek().lexeme;++pos_;return std::make_unique<LiteralExpr>(v);}if(k==TokenKind::Identifier){auto n=peek().lexeme;++pos_;return std::make_unique<NameExpr>(n);}errors_.push_back("expected expression at line "+std::to_string(peek().location.line));if(k!=TokenKind::End)++pos_;return std::make_unique<LiteralExpr>("0");}
}
